SELECT EXISTS(
    SELECT 1
    FROM buyer_company
    WHERE credit_code = #{creditCode}

        AND id != #{excludeId}

)

SELECT EXISTS(
    SELECT 1
    FROM buyer_company
    WHERE open_corpid = #{openCorpId}

        AND id != #{excludeId}

)

